const I18n = {
  KEY: 'villagehub_lang',
  get lang() { try { return localStorage.getItem(this.KEY) === 'ta' ? 'ta' : 'en'; } catch (e) { return 'en'; } },
  get ta() { return this.lang === 'ta'; },
  locale() { return this.ta ? 'ta-IN' : 'en-IN'; },
  label(l) { return (l || this.lang) === 'ta' ? 'தமிழ்' : 'English'; },
  set(l) {
    try { localStorage.setItem(this.KEY, l === 'ta' ? 'ta' : 'en'); } catch (e) { /* ignore */ }
    this.sync();
    if (window.App && App.top()) App.refresh();
    UI.toast(l === 'ta' ? 'மொழி: தமிழ்' : 'Language: English', 'ok');
  },
  sync() {
    document.documentElement.setAttribute('data-lang', this.lang);
    const ph = document.getElementById('phone'); if (ph) ph.setAttribute('lang', this.ta ? 'ta' : 'en');
    document.querySelectorAll('[data-lang-btn]').forEach(b => b.classList.toggle('on', b.dataset.langBtn === this.lang));
  },
  // Translate one string (keeps surrounding whitespace). English passes through unchanged.
  t(raw) {
    if (!this.ta || raw == null) return raw;
    const s = String(raw).replace(/\s+/g, ' ').trim();
    if (!s || !/[A-Za-z]/.test(s)) return raw;
    const r = this._one(s);
    if (r == null) return raw;
    const lead = String(raw).match(/^\s*/)[0], trail = String(raw).match(/\s*$/)[0];
    return lead + r + trail;
  },
  _one(s) {
    if (Object.prototype.hasOwnProperty.call(TA, s)) return TA[s];
    // Split "A · B · C" lines first, so a broad pattern never swallows the separator.
    if (s.includes(' · ')) {
      const parts = s.split(' · '), out = parts.map(p => { const r = this._one(p); return r == null ? p : r; });
      if (out.some((x, i) => x !== parts[i])) return out.join(' · ');
    }
    for (const [re, fn] of TA_P) { const m = s.match(re); if (m) return fn(...m.slice(1)); }
    if (s.startsWith('· ')) { const r = this._one(s.slice(2)); if (r != null) return '· ' + r; }
    const m = s.match(/^(.*?)([.:!?…,])$/);
    if (m && Object.prototype.hasOwnProperty.call(TA, m[1])) return TA[m[1]] + m[2];
    return null;
  },
  // Translate a rendered subtree in place: text nodes plus placeholder / aria-label / title attributes.
  apply(root) {
    if (!this.ta || !root) return;
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: n => n.parentElement && n.parentElement.closest('textarea,script,style,[data-raw]') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
    const nodes = []; let n; while ((n = w.nextNode())) nodes.push(n);
    nodes.forEach(x => { const v = this.t(x.nodeValue); if (v !== x.nodeValue) x.nodeValue = v; });
    root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(e => ['placeholder', 'aria-label', 'title'].forEach(a => { const v = e.getAttribute(a); if (v) { const t = this.t(v); if (t !== v) e.setAttribute(a, t); } }));
  },
  // Language picker sheet (Profile, Login).
  sheet() {
    UI.sheet(`<div class="sheet-title">${this.ta ? 'மொழி' : 'Language'}</div><div class="mt8">${[['en', 'English', 'English'], ['ta', 'தமிழ்', 'Tamil']].map(([k, l, s]) => `<button class="opt ${this.lang === k ? 'on' : ''}" onclick="UI.close(true);I18n.set('${k}')"><span class="radio"></span><span class="grow"><span class="b">${l}</span><span class="xs muted" data-raw>${s}</span></span></button>`).join('')}</div>`);
  }
};
